<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$run=$db->prepare("INSERT INTO marketing_automation_runs(job_name,status,result_message) VALUES('marketing-automation','success','started')");$run->execute();$score=0;$leads=$db->query('SELECT id FROM leads')->fetchAll(PDO::FETCH_COLUMN);foreach($leads as $leadId){$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN event_type='page_view' THEN 1 WHEN event_type IN ('form_submit','email_open','email_click') THEN 5 WHEN event_type='conversion' THEN 25 ELSE 0 END),0) FROM marketing_events WHERE lead_id=? AND occurred_at>=DATE_SUB(NOW(),INTERVAL 90 DAY)");$q->execute([(int)$leadId]);$score=(int)$q->fetchColumn();$grade=$score>=50?'qualified':($score>=25?'hot':($score>=10?'warm':'cold'));$u=$db->prepare('INSERT INTO lead_marketing_scores(lead_id,score,grade,last_calculated_at) VALUES(?,?,?,NOW()) ON DUPLICATE KEY UPDATE score=VALUES(score),grade=VALUES(grade),last_calculated_at=NOW()');$u->execute([(int)$leadId,$score,$grade]);}echo date('c')." marketing automation complete; scored ".count($leads)." leads\n";